package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class FilteringParserDelegate_nextToken_TriageGen0Test {

    private JsonParser delegate;
    private TokenFilter filter;
    // Using a subclass or spy because FilteringParserDelegate is often used as a base
    private FilteringParserDelegate delegateInstance;

    @Before
    public void setUp() throws Exception {
        delegate = mock(JsonParser.class);
        filter = mock(TokenFilter.class);
        // We create a concrete instance. Since it's a delegate, we might need to mock the protected methods 
        // or use a spy to control the internal state.
        delegateInstance = spy(new FilteringParserDelegate(delegate, filter, false, false) {
            @Override
            protected JsonToken _nextToken2() throws IOException {
                return JsonToken.VALUE_STRING; // Default fallback for testing
            }
            @Override
            protected JsonToken _nextTokenWithBuffering(TokenFilterContext buffRoot) throws IOException {
                return JsonToken.VALUE_STRING;
            }
        });
    }

    private void setField(String name, Object value) throws Exception {
        Field field = FilteringParserDelegate.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(delegateInstance, value);
    }

    private void setProtectedField(String name, Object value) throws Exception {
        Field field = FilteringParserDelegate.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(delegateInstance, value);
    }

    @Test
    public void testNextToken_NullExposedContext_EndStruct() throws Exception {
        setProtectedField("_exposedContext", null);
        setProtectedField("_includePath", false);

        JsonToken endToken = JsonToken.END_OBJECT;
        JsonToken currentToken = mock(JsonToken.class);
        when(currentToken.isStructEnd()).thenReturn(true);

        setProtectedField("_currToken", currentToken);

        TokenFilterContext headContext = mock(TokenFilterContext.class);
        when(headContext.isStartHandled()).thenReturn(true);
        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        assertNull(result);
        assertNull(getInternalCurrToken());
    }

    @Test
    public void testNextToken_NullExposedContext_ScalarIncludeAll() throws Exception {
        setProtectedField("_exposedContext", null);
        setProtectedField("_includePath", false);
        setProtectedField("_itemFilter", TokenFilter.INCLUDE_ALL);

        JsonToken scalarToken = mock(JsonToken.class);
        when(scalarToken.isScalarValue()).thenReturn(true);
        setProtectedField("_currToken", scalarToken);

        TokenFilterContext headContext = mock(TokenFilterContext.class);
        when(headContext.isStartHandled()).thenReturn(false);
        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        assertNull(result);
        assertNull(getInternalCurrToken());
    }

    @Test
    public void testNextToken_BufferedContext_ReturnsNextToken() throws Exception {
        TokenFilterContext mockContext = mock(TokenFilterContext.class);
        JsonToken nextT = JsonToken.FIELD_NAME;
        when(mockContext.nextTokenToRead()).thenReturn(nextT);

        setProtectedField("_exposedContext", mockContext);

        JsonToken result = delegateInstance.nextToken();

        assertEquals(nextT, result);
        assertEquals(nextT, getInternalCurrToken());
    }

    @Test
    public void testNextToken_BufferedContext_Empty_TraverseChain() throws Exception {
        TokenFilterContext headContext = mock(TokenFilterContext.class);
        TokenFilterContext childContext = mock(TokenFilterContext.class);

        when(childContext.nextTokenToRead()).thenReturn(null);
        when(headContext.findChildOf(childContext)).thenReturn(headContext);
        when(headContext.inArray()).thenReturn(true);
        when(delegate.getCurrentToken()).thenReturn(JsonToken.START_ARRAY);

        setProtectedField("_exposedContext", childContext);
        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        assertEquals(JsonToken.START_ARRAY, result);
        assertNull(getInternalExposedContext());
    }

    @Test
    public void testNextToken_DelegateReturnsNull() throws Exception {
        setProtectedField("_exposedContext", null);
        when(delegate.nextToken()).thenReturn(null);

        JsonToken result = delegateInstance.nextToken();

        assertNull(result);
        assertNull(getInternalCurrToken());
    }

    @Test
    public void testNextToken_StartArray_IncludeAll() throws Exception {
        setProtectedField("_exposedContext", null);
        when(delegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        setProtectedField("_itemFilter", TokenFilter.INCLUDE_ALL);

        TokenFilterContext headContext = mock(TokenFilterContext.class);
        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        assertEquals(JsonToken.START_ARRAY, result);
        verify(headContext).createChildArrayContext(TokenFilter.INCLUDE_ALL, true);
    }

    @Test
    public void testNextToken_StartObject_FilterNull_Skips() throws Exception {
        setProtectedField("_exposedContext", null);
        when(delegate.nextToken()).thenReturn(JsonToken.START_OBJECT);
        setProtectedField("_itemFilter", null);

        TokenFilterContext headContext = mock(TokenFilterContext.class);
        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        // result comes from _nextToken2() which we mocked to return VALUE_STRING
        assertEquals(JsonToken.VALUE_STRING, result);
        verify(delegate).skipChildren();
    }

    @Test
    public void testNextToken_EndArray_ReturnsToken() throws Exception {
        setProtectedField("_exposedContext", null);
        when(delegate.nextToken()).thenReturn(JsonToken.END_ARRAY);

        TokenFilterContext headContext = mock(TokenFilterContext.class);
        when(headContext.isStartHandled()).thenReturn(true);
        when(headContext.getFilter()).thenReturn(TokenFilter.INCLUDE_ALL);
        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        assertEquals(JsonToken.END_ARRAY, result);
        verify(headContext).getParent();
    }

    @Test
    public void testNextToken_FieldName_IncludeAll() throws Exception {
        setProtectedField("_exposedContext", null);
        when(delegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(delegate.getCurrentName()).thenReturn("testField");

        TokenFilterContext headContext = mock(TokenFilterContext.class);
        when(headContext.setFieldName("testField")).thenReturn(TokenFilter.INCLUDE_ALL);
        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
    }

    @Test
    public void testNextToken_Scalar_IncludeAll() throws Exception {
        setProtectedField("_exposedContext", null);
        when(delegate.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        setProtectedField("_itemFilter", TokenFilter.INCLUDE_ALL);

        TokenFilterContext headContext = mock(TokenFilterContext.class);
        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        assertEquals(JsonToken.VALUE_NUMBER_INT, result);
    }

    @Test
    public void testNextToken_Scalar_FilterCheck() throws Exception {
        setProtectedField("_exposedContext", null);
        when(delegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        setProtectedField("_itemFilter", mock(TokenFilter.class)); // Not INCLUDE_ALL

        TokenFilterContext headContext = mock(TokenFilterContext.class);
        TokenFilter checkFilter = mock(TokenFilter.class);
        when(headContext.checkValue(any())).thenReturn(checkFilter);
        when(checkFilter.includeValue(any())).thenReturn(true);

        setProtectedField("_headContext", headContext);

        JsonToken result = delegateInstance.nextToken();

        assertEquals(JsonToken.VALUE_STRING, result);
        verify(checkFilter).includeValue(delegate);
    }

    private JsonToken getInternalCurrToken() throws Exception {
        Field field = FilteringParserDelegate.class.getDeclaredField("_currToken");
        field.setAccessible(true);
        return (JsonToken) field.get(delegateInstance);
    }

    private TokenFilterContext getInternalExposedContext() throws Exception {
        Field field = FilteringParserDelegate.class.getDeclaredField("_exposedContext");
        field.setAccessible(true);
        return (TokenFilterContext) field.get(delegateInstance);
    }
}
